// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // airdrop to a fuzzed actor: reduces totalRemaining below totalDistributed
        vm.prank(actor);
        c.getTokens();

        uint256 distrBefore = c.totalDistributed();
        vm.assume(distrBefore > c.totalRemaining()); // divergence exists in mutant

        // owner (deployer = this contract) reseats state via NETM
        vm.prank(address(this));
        c.NETM();

        // general rule: owner's balance always equals totalDistributed
        assertTrue(c.balanceOf(address(this)) == c.totalDistributed());
    }
}
